import os, sys, json, hashlib, platform, datetime
import numpy as np
import pandas as pd
from scipy import stats
import plotly.graph_objects as go

SEED = 20240613
N_BOOT = 10000
CONTACT_CUTOFF_A = 5.0
np.random.seed(SEED)

RESULTS_DIR = os.environ.get("RESULTS_DIR", "results")
os.makedirs(RESULTS_DIR, exist_ok=True)

# ---------- 1. DATA LOADING (injected variable only) ----------
pdb_path = DATA_6M0J_PDB  # pre-injected absolute path
if not os.path.exists(pdb_path):
    print(f"FATAL: PDB file not found at {pdb_path}", file=sys.stderr)
    sys.exit(1)

def sha256_file(path, chunk=1 << 20):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for blk in iter(lambda: f.read(chunk), b""):
            h.update(blk)
    return h.hexdigest()

def get_resolution(path):
    with open(path) as f:
        for line in f:
            if line.startswith("REMARK   2 RESOLUTION."):
                try:
                    return float(line.split()[3])
                except (ValueError, IndexError):
                    return None
    return None

def parse_pdb_minimal(path):
    residues = {}
    with open(path) as f:
        for line in f:
            rec = line[:6].strip()
            if rec == "ATOM":
                altloc = line[16]
                if altloc not in (" ", "A"):
                    continue
                atom_name = line[12:16].strip()
                resname = line[17:20].strip()
                chain = line[21]
                resseq = int(line[22:26])
                occ = float(line[54:60] or "1.0")
                x, y, z = float(line[30:38]), float(line[38:46]), float(line[46:54])
                key = (chain, resseq)
                if key not in residues:
                    residues[key] = {"resname": resname, "atoms": {}}
                residues[key]["atoms"][atom_name] = (x, y, z, occ)
    return residues

def min_heavy_atom_distance(res_a, res_b):
    heavy_a = {k: v for k, v in res_a["atoms"].items() if not k.startswith("H")}
    heavy_b = {k: v for k, v in res_b["atoms"].items() if not k.startswith("H")}
    dmin = np.inf
    for _, (x1, y1, z1, _) in heavy_a.items():
        for _, (x2, y2, z2, _) in heavy_b.items():
            d = np.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2 + (z1 - z2) ** 2)
            if d < dmin:
                dmin = d
    return float(dmin)

file_hash = sha256_file(pdb_path)
resolution = get_resolution(pdb_path)
residues = parse_pdb_minimal(pdb_path)

chains_present = sorted(set(c for (c, _) in residues.keys()))
rbd_chain = "E" if "E" in chains_present else chains_present[-1]
ace2_chain = "A" if "A" in chains_present else chains_present[0]

# ---------- 2. MEASUREMENTS ----------
pairs = [((rbd_chain, 498), (ace2_chain, 353)),
         ((rbd_chain, 498), (ace2_chain, 38)),
         ((rbd_chain, 501), (ace2_chain, 353)),
         ((rbd_chain, 501), (ace2_chain, 38))]

records = []
for ra, rb in pairs:
    label = f"{ra[0]}{ra[1]}-{rb[0]}{rb[1]}"
    if ra in residues and rb in residues:
        d = min_heavy_atom_distance(residues[ra], residues[rb])
        records.append({"pair": label,
                        "rbd_res": ra[1], "ace2_res": rb[1],
                        "min_heavy_atom_distance_A": d,
                        "in_contact_5A": bool(d <= CONTACT_CUTOFF_A)})
    else:
        records.append({"pair": label, "rbd_res": ra[1], "ace2_res": rb[1],
                        "min_heavy_atom_distance_A": np.nan,
                        "in_contact_5A": False})

df = pd.DataFrame(records)

# ---------- 3. RIGOR: control vs treatment + permutation test ----------
# Treatment group: distances for the hypothesized hot-spot pairs (498-K353, 498-D38)
# Control group: distances for the predicted/secondary pairs (501-K353, 501-D38)
treatment_values = df[df["rbd_res"] == 498]["min_heavy_atom_distance_A"].dropna().values
control_values = df[df["rbd_res"] == 501]["min_heavy_atom_distance_A"].dropna().values

def permutation_test(a, b, n_perm=10000):
    a = np.asarray(a, float); b = np.asarray(b, float)
    if len(a) == 0 or len(b) == 0:
        return np.nan, np.nan
    obs = np.mean(a) - np.mean(b)
    pooled = np.concatenate([a, b])
    rng = np.random.default_rng(SEED)
    count = 0
    for _ in range(n_perm):
        perm = rng.permutation(pooled)
        if abs(np.mean(perm[:len(a)]) - np.mean(perm[len(a):])) >= abs(obs):
            count += 1
    return obs, (count + 1) / (n_perm + 1)

obs_diff, p_perm = permutation_test(treatment_values, control_values)
# Welch t-test as secondary evidence
if len(treatment_values) > 1 and len(control_values) > 1:
    t_stat, p_ttest = stats.ttest_ind(treatment_values, control_values, equal_var=False)
else:
    t_stat, p_ttest = np.nan, np.nan

# Bootstrap CI for the mean of all four hot-spot distances
all_d = df["min_heavy_atom_distance_A"].dropna().values
if len(all_d) >= 2:
    rng = np.random.default_rng(SEED)
    boots = np.array([np.mean(rng.choice(all_d, size=len(all_d), replace=True))
                      for _ in range(N_BOOT)])
    ci_lo, ci_hi = np.percentile(boots, [2.5, 97.5])
    theta_hat = float(np.mean(all_d))
    converged = len(np.unique(np.round(boots, 6))) > 100
else:
    theta_hat, ci_lo, ci_hi, converged = np.nan, np.nan, np.nan, False

# Effect size: Cohen's d (pooled std)
def cohens_d(a, b):
    a, b = np.asarray(a, float), np.asarray(b, float)
    if len(a) < 2 or len(b) < 2:
        return np.nan
    sp = np.sqrt(((len(a)-1)*np.var(a, ddof=1) + (len(b)-1)*np.var(b, ddof=1)) / (len(a)+len(b)-2))
    return (np.mean(a) - np.mean(b)) / sp if sp > 0 else np.nan

effect_d = cohens_d(treatment_values, control_values)

# ---------- 4. PERSISTENCE ----------
csv_path = os.path.join(RESULTS_DIR, "raw_data.csv")
df.to_csv(csv_path, index=False)

stats_df = pd.DataFrame([{
    "theta_hat_mean_distance_A": theta_hat,
    "ci95_lo_A": ci_lo, "ci95_hi_A": ci_hi,
    "treatment_mean_498_A": float(np.mean(treatment_values)) if len(treatment_values) else np.nan,
    "control_mean_501_A": float(np.mean(control_values)) if len(control_values) else np.nan,
    "obs_diff_A": obs_diff, "p_permutation": p_perm,
    "t_statistic": t_stat, "p_ttest": p_ttest, "cohens_d": effect_d,
    "n_bootstrap": N_BOOT, "bootstrap_converged": converged,
    "resolution_A": resolution, "file_sha256": file_hash,
}])
stats_df.to_csv(os.path.join(RESULTS_DIR, "stats_summary.csv"), index=False)

# ---------- 5. RENDERING ----------
fig = go.Figure()
fig.add_trace(go.Bar(
    x=df["pair"], y=df["min_heavy_atom_distance_A"],
    marker_color=["crimson" if c else "gray" for c in df["in_contact_5A"]],
    text=[f"{v:.2f} A" if np.isfinite(v) else "NA" for v in df["min_heavy_atom_distance_A"]],
    textposition="outside"))
fig.add_hline(y=CONTACT_CUTOFF_A, line_dash="dash", line_color="black",
              annotation_text="5.0 A contact cutoff")
fig.add_hline(y=4.5, line_dash="dot", line_color="blue",
              annotation_text="4.5 A hot-spot threshold")
fig.update_layout(title="6M0J RBD-ACE2 Hot-Spot Network: Min Heavy-Atom Distances",
                  yaxis_title="Min heavy-atom distance (A)", xaxis_title="Residue pair",
                  template="plotly_white")
fig.write_image(os.path.join(RESULTS_DIR, "viz.png"), scale=3)

# ---------- 6. VERDICT ----------
hypothesis_checks = {
    "498_within_4.5A_of_K353": False,
    "498_within_5.0A_of_D38": False,
    "501_contacts_network_5A": False,
}
for _, r in df.iterrows():
    d = r["min_heavy_atom_distance_A"]
    if not np.isfinite(d):
        continue
    if r["rbd_res"] == 498 and r["ace2_res"] == 353 and d <= 4.5:
        hypothesis_checks["498_within_4.5A_of_K353"] = True
    if r["rbd_res"] == 498 and r["ace2_res"] == 38 and d <= 5.0:
        hypothesis_checks["498_within_5.0A_of_D38"] = True
    if r["rbd_res"] == 501 and d <= 5.0:
        hypothesis_checks["501_contacts_network_5A"] = True

supported = all(hypothesis_checks.values())
confidence = 0.95 if supported else (0.5 if any(hypothesis_checks.values()) else 0.05)

report = {
    "supported": bool(supported),
    "confidence": float(confidence),
    "details": {
        "hypothesis_checks": hypothesis_checks,
        "theta_hat_mean_distance_A": theta_hat,
        "ci95_bootstrap_A": [float(ci_lo), float(ci_hi)],
        "treatment_mean_498_A": float(np.mean(treatment_values)) if len(treatment_values) else None,
        "control_mean_501_A": float(np.mean(control_values)) if len(control_values) else None,
        "obs_diff_A": float(obs_diff) if np.isfinite(obs_diff) else None,
        "p_permutation": float(p_perm) if np.isfinite(p_perm) else None,
        "p_ttest": float(p_ttest) if np.isfinite(p_ttest) else None,
        "t_statistic": float(t_stat) if np.isfinite(t_stat) else None,
        "cohens_d": float(effect_d) if np.isfinite(effect_d) else None,
        "resolution_A": resolution,
        "chains_present": chains_present,
        "n_bootstrap": N_BOOT,
        "bootstrap_converged": bool(converged),
        "file_sha256": file_hash,
        "raw_data_csv": csv_path,
    },
}
print(json.dumps(report, indent=2))
